import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String value = scanner.next();
        Deque<Character> stack = new ArrayDeque<>();
        boolean valid = true;
        for (char bracket : value.toCharArray()) {
            if (bracket == '(' || bracket == '[' || bracket == '{') stack.push(bracket);
            else {
                if (stack.isEmpty()) { valid = false; break; }
                char opening = stack.pop();
                if ((bracket == ')' && opening != '(') || (bracket == ']' && opening != '[') || (bracket == '}' && opening != '{')) { valid = false; break; }
            }
        }
        System.out.println(valid && stack.isEmpty() ? "true" : "false");
    }
}

#include <iostream>
#include <stack>
#include <string>
using namespace std;

int main() {
    string value;
    cin >> value;
    stack<char> openings;
    bool valid = true;
    for (char bracket : value) {
        if (bracket == '(' || bracket == '[' || bracket == '{') openings.push(bracket);
        else {
            if (openings.empty()) { valid = false; break; }
            char opening = openings.top();
            openings.pop();
            if ((bracket == ')' && opening != '(') || (bracket == ']' && opening != '[') || (bracket == '}' && opening != '{')) { valid = false; break; }
        }
    }
    cout << (valid && openings.empty() ? "true" : "false") << endl;
    return 0;
}
